function read(input={}){object(input,['include_cells']);if(own(input,'include_cells')&&typeof input.include_cells!=='boolean')throw Error('include_cells must be boolean');const s=api.state,b=s.blockSize*25.4,rows=s.cells.length,columns=s.cells[0].length,counts={};for(const cell of s.cells.flat())if(cell)counts[cell.type]=(counts[cell.type]||0)+1;const usedW=columns*b+(columns-1)*s.joint,usedH=rows*b+(rows-1)*s.joint;return {display_units:window.jaliUnits.get(),available_rhythms:api.rhythms,available_combos:api.combos.map(c=>({id:c.id,name:c.name,rows:c.grid.length,columns:c.grid[0].length})),rhythm_id:s.preset||null,available_blocks:api.types.map(([id,name])=>({id,name})),coordinate_system:'Rows and columns are 1-based. Row 1 is the TOP. Rotations are clockwise as seen from the front.',opening:{width_ft:s.width,height_ft:s.height,width_mm:+(s.width*304.8).toFixed(1),height_mm:+(s.height*304.8).toFixed(1),sill_mm:s.sill||0},block:{width_mm:+b.toFixed(1),height_mm:+b.toFixed(1),depth_mm:s.depth||100,joint_mm:s.joint,finish:s.color},grid:{rows,columns,placed:s.cells.flat().filter(Boolean).length,clearance_width_mm:+(s.width*304.8-usedW).toFixed(1),clearance_height_mm:+(s.height*304.8-usedH).toFixed(1)},counts,row_summary:s.cells.map((row,r)=>({row:r+1,counts:row.reduce((a,c)=>(a[c?.type||'empty']=(a[c?.type||'empty']||0)+1,a),{})})),selection:api.selection?{row:api.selection.r+1,column:api.selection.c+1,count:api.selectedCells.length,...(input.include_cells?{selected_cells:api.selectedCells.map(p=>({row:p.r+1,column:p.c+1}))}:{})}:null,lighting:window.jaliScene?.getLight()||null,view:document.querySelector('#drawing').hidden?'3d':'elevation',...(input.include_cells?{cells:s.cells.map(row=>row.map(c=>c?{...c}:null))}:{})}}
